import { Component, inject, signal } from '@angular/core';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import {
  TablerIconComponent, IconBell, IconSearch, IconChevronDown, IconPlus, IconStar,
  IconLayoutDashboard, IconUsers, IconCalendarTime, IconReportAnalytics,
} from '@tabler/icons-angular';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { HrmTopNav, HrmNavItem, HrmButton, HrmDropdown } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';

/** Doc page · Top Nav (Appshell) — bám đúng bộ ví dụ chuẩn: With Logo / Centered / Enterprise / Multiple Dropdowns / Hover Menu / Mega Menu. Song ngữ qua i18n docs.topNav.*. */
@Component({
  selector: 'sg-doc-top-nav',
  imports: [TranslateModule, TablerIconComponent, NzDropDownModule, HrmTopNav, HrmButton, HrmDropdown, SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow],
  template: `
    <sg-doc category="Appshell" [title]="'docs.topNav.title' | translate" [desc]="'docs.topNav.desc' | translate">

      <div sgOverview>
        <div class="tn-frame">
          <hrm-top-nav [items]="items" [selectedKey]="sel()" (itemClick)="sel.set($event.key)" [logoSrc]="logo">
            <button tnActions type="button" class="tn-ico" [attr.aria-label]="'docs.topNav.ariaNotify' | translate"><tabler-icon [icon]="bell" [size]="20" /></button>
            <span tnActions class="tn-av">ĐV</span>
          </hrm-top-nav>
        </div>
        <p style="font-size: var(--fs-13);color:var(--text-sub);margin:12px 0 0;max-width:56ch;line-height:1.5">{{ 'docs.topNav.ovNote' | translate }}</p>
      </div>

      <div sgUsage>
        <sg-use
          [purpose]="'docs.topNav.purpose' | translate"
          [when]="when"
          [behavior]="'docs.topNav.behavior' | translate"
          [avoid]="'docs.topNav.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do><span [innerHTML]="'docs.topNav.do1' | translate"></span></sg-do>
        <sg-do><span [innerHTML]="'docs.topNav.do2' | translate"></span></sg-do>
        <sg-dont>{{ 'docs.topNav.dont1' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.topNav.exCenterT' | translate"
          [desc]="'docs.topNav.exCenterD' | translate">
          <sg-row>
            <div class="tn-frame" style="width:100%">
              <hrm-top-nav align="center" [items]="items" [selectedKey]="selC()" (itemClick)="selC.set($event.key)" [logoSrc]="logo">
                <button tnActions type="button" class="tn-ghost">{{ 'docs.topNav.login' | translate }}</button>
                <hrm-button tnActions variant="primary" size="sm">{{ 'docs.topNav.tryFree' | translate }}</hrm-button>
              </hrm-top-nav>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.topNav.exEnterpriseT' | translate"
          [desc]="'docs.topNav.exEnterpriseD' | translate">
          <sg-row>
            <div class="tn-frame" style="width:100%">
              <hrm-top-nav [items]="iconItems" [selectedKey]="selE()" (itemClick)="selE.set($event.key)" [logoSrc]="logo">
                <span tnActions class="tn-search" [class.is-open]="tnSearchOpen()" (click)="tnSearchOpen.set(!tnSearchOpen())"><tabler-icon [icon]="search" [size]="16" /><input [placeholder]="'docs.topNav.searchPh' | translate" (click)="$event.stopPropagation()" /></span>
                <button tnActions type="button" class="tn-ico" [attr.aria-label]="'docs.topNav.ariaNotify' | translate"><tabler-icon [icon]="bell" [size]="20" /></button>
                <hrm-button tnActions variant="primary" size="sm"><tabler-icon [icon]="plus" [size]="16" /> {{ 'docs.topNav.create' | translate }}</hrm-button>
              </hrm-top-nav>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.topNav.exMultiT' | translate"
          [desc]="'docs.topNav.exMultiD' | translate">
          <sg-row>
            <div class="tn-frame" style="width:100%">
              <hrm-top-nav [logoSrc]="logo">
                <button tnNav type="button" class="tn-navbtn" [hrmDropdown]="mProd" hrmDropdownTrigger="hover">{{ 'docs.topNav.navProduct' | translate }} <tabler-icon [icon]="chev" [size]="15" /></button>
                <button tnNav type="button" class="tn-navbtn" [hrmDropdown]="mSol" hrmDropdownTrigger="hover">{{ 'docs.topNav.navSolution' | translate }} <tabler-icon [icon]="chev" [size]="15" /></button>
                <button tnNav type="button" class="tn-navbtn" [hrmDropdown]="mRes" hrmDropdownTrigger="hover">{{ 'docs.topNav.navResource' | translate }} <tabler-icon [icon]="chev" [size]="15" /></button>
                <button tnActions type="button" class="tn-ghost">{{ 'docs.topNav.login' | translate }}</button>
              </hrm-top-nav>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.topNav.exHoverT' | translate"
          [desc]="'docs.topNav.exHoverD' | translate">
          <sg-row>
            <div class="tn-frame" style="width:100%">
              <hrm-top-nav [items]="items2" selectedKey="dash" [logoSrc]="logo">
                <button tnActions type="button" class="tn-navbtn" [hrmDropdown]="mHover" hrmDropdownTrigger="hover">{{ 'docs.topNav.navProduct' | translate }} <tabler-icon [icon]="chev" [size]="15" /></button>
                <span tnActions class="tn-av">ĐV</span>
              </hrm-top-nav>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.topNav.exMegaT' | translate"
          [desc]="'docs.topNav.exMegaD' | translate">
          <sg-row>
            <div class="tn-frame" style="width:100%">
              <hrm-top-nav [logoSrc]="logo">
                <button tnNav type="button" class="tn-navbtn" [hrmDropdown]="mMega" hrmDropdownTrigger="hover">{{ 'docs.topNav.navExplore' | translate }} <tabler-icon [icon]="chev" [size]="15" /></button>
                <button tnNav type="button" class="tn-navbtn">{{ 'docs.topNav.navPricing' | translate }}</button>
                <hrm-button tnActions variant="primary" size="sm">{{ 'docs.topNav.tryFree' | translate }}</hrm-button>
              </hrm-top-nav>
            </div>
          </sg-row>
        </sg-example>
      </div>
    </sg-doc>

    <!-- Multiple Dropdowns: 3 menu link đơn giản -->
    <nz-dropdown-menu #mProd="nzDropdownMenu"><div class="dd">
      <a class="dd-row">{{ 'docs.topNav.ddAttendance' | translate }}</a><a class="dd-row">{{ 'docs.topNav.ddPayroll' | translate }}</a><a class="dd-row">{{ 'docs.topNav.ddRecruit' | translate }}</a>
    </div></nz-dropdown-menu>
    <nz-dropdown-menu #mSol="nzDropdownMenu"><div class="dd">
      <a class="dd-row">{{ 'docs.topNav.ddForEnterprise' | translate }}</a><a class="dd-row">{{ 'docs.topNav.ddForRetail' | translate }}</a><a class="dd-row">{{ 'docs.topNav.ddForFactory' | translate }}</a>
    </div></nz-dropdown-menu>
    <nz-dropdown-menu #mRes="nzDropdownMenu"><div class="dd">
      <a class="dd-row">{{ 'docs.topNav.ddDocs' | translate }}</a><a class="dd-row">{{ 'docs.topNav.ddGuide' | translate }}</a><a class="dd-row">{{ 'docs.topNav.ddBlog' | translate }}</a>
    </div></nz-dropdown-menu>

    <!-- Hover Menu: sản phẩm icon + mô tả -->
    <nz-dropdown-menu #mHover="nzDropdownMenu"><div class="dd dd-rich">
      @for (p of products; track p.name) {
        <a class="dd-item">
          <span class="dd-ic"><tabler-icon [icon]="$any(p.icon)" [size]="18" /></span>
          <span><span class="dd-name">{{ p.name }}</span><span class="dd-desc">{{ p.desc }}</span></span>
        </a>
      }
    </div></nz-dropdown-menu>

    <!-- Mega Menu: lưới sản phẩm + thẻ nổi bật -->
    <nz-dropdown-menu #mMega="nzDropdownMenu"><div class="mega">
      <div class="mega-grid">
        @for (p of products; track p.name) {
          <a class="dd-item">
            <span class="dd-ic"><tabler-icon [icon]="$any(p.icon)" [size]="18" /></span>
            <span><span class="dd-name">{{ p.name }}</span><span class="dd-desc">{{ p.desc }}</span></span>
          </a>
        }
      </div>
      <div class="mega-promo">
        <tabler-icon [icon]="star" [size]="22" />
        <span class="mega-promo-t">VnResource 2026</span>
        <span class="mega-promo-d">{{ 'docs.topNav.promoDesc' | translate }}</span>
        <span class="mega-promo-c">{{ 'docs.topNav.promoCta' | translate }}</span>
      </div>
    </div></nz-dropdown-menu>
  `,
  styles: [`
    .tn-frame { border: 1px solid var(--border-sub); border-radius: var(--radius-lg); overflow: hidden; }
    .tn-ico { display: grid; place-items: center; width: 36px; height: 36px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .tn-ico:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    .tn-av { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--primary-base); color: #fff; font-size: var(--fs-13); font-weight: 600; }
    .tn-search { display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface-subtle); color: var(--text-sub); }
    .tn-search input { border: 0; background: transparent; outline: none; font: inherit; font-size: var(--fs-13); color: var(--text-body); width: 160px; }
    /* Responsive: chỉ khi RẤT hẹp (.tn--narrow, lib bật <560px) → search thu thành ICON.
       Độc lập ngưỡng hamburger → search vẫn full ở 560–820. ::ng-deep vì .tn--narrow là lib. */
    ::ng-deep .tn--narrow .tn-search { flex: none; box-sizing: border-box; width: 36px; height: 36px; padding: 0; justify-content: center; cursor: pointer; background: transparent; border: 0; color: var(--text-sub); }
    ::ng-deep .tn--narrow .tn-search:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    /* Bấm icon → mở lại ô nhập đầy đủ (dù đang hẹp). */
    ::ng-deep .tn--narrow .tn-search.is-open { width: auto; height: auto; padding: 6px 10px; justify-content: flex-start; background: var(--bg-surface-subtle); border: 1px solid var(--border-sub); }
    ::ng-deep .tn--narrow .tn-search.is-open input { display: inline; }
    ::ng-deep .tn--narrow .tn-search input { display: none; }
    .tn-ghost { border: 0; background: transparent; cursor: pointer; font: inherit; font-size: var(--fs-14); color: var(--text-body); padding: 7px 12px; border-radius: var(--radius-lg); }
    .tn-ghost:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    /* Nav button (slot tnNav) — trông như tn-item, mở dropdown */
    .tn-navbtn { display: inline-flex; align-items: center; gap: 4px; border: 0; background: transparent; cursor: pointer; font: inherit; font-size: var(--fs-14); color: var(--text-body); padding: 7px 12px; border-radius: var(--radius-lg); white-space: nowrap; }
    .tn-navbtn:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }

    /* Panel dropdown (render trong overlay — inline/global qua ::ng-deep) */
    ::ng-deep .dd { min-width: 200px; padding: 6px; background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-xl); box-shadow: var(--shadow-regular-md); }
    ::ng-deep .dd-row { display: block; padding: 8px 12px; border-radius: var(--radius-md); font-size: var(--fs-14); color: var(--text-body); cursor: pointer; text-decoration: none; }
    ::ng-deep .dd-row:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    ::ng-deep .dd-rich { min-width: 320px; }
    ::ng-deep .dd-item { display: flex; align-items: flex-start; gap: 12px; padding: 10px 12px; border-radius: var(--radius-lg); cursor: pointer; text-decoration: none; }
    ::ng-deep .dd-item:hover { background: var(--bg-surface-subtle); }
    ::ng-deep .dd-ic { display: grid; place-items: center; width: 36px; height: 36px; border-radius: var(--radius-md); background: var(--primary-bg-subtle); color: var(--primary-base); flex: none; }
    ::ng-deep .dd-name { display: block; font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); }
    ::ng-deep .dd-desc { display: block; font-size: var(--fs-12); color: var(--text-sub); }
    ::ng-deep .mega { display: flex; gap: 12px; padding: 12px; min-width: 560px; background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-xl); box-shadow: var(--shadow-regular-lg); }
    ::ng-deep .mega-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; flex: 1; }
    ::ng-deep .mega-promo { display: flex; flex-direction: column; gap: 6px; width: 200px; padding: 16px; border-radius: var(--radius-lg); background: var(--primary-bg-subtle); color: var(--primary-base); }
    ::ng-deep .mega-promo-t { font-size: var(--fs-15); font-weight: 700; color: var(--text-strong); }
    ::ng-deep .mega-promo-d { font-size: var(--fs-12); color: var(--text-sub); }
    ::ng-deep .mega-promo-c { margin-top: auto; font-size: var(--fs-13); font-weight: 600; color: var(--primary-base); }
  `],
})
export class SgDocTopNav {
  private readonly t = inject(TranslateService);
  private tr(key: string): string { return this.t.instant('docs.topNav.' + key); }

  protected readonly bell = IconBell;
  protected readonly search = IconSearch;
  protected readonly chev = IconChevronDown;
  protected readonly plus = IconPlus;
  protected readonly star = IconStar;
  protected readonly logo = '/assets/vnr-logo-full.svg';
  protected readonly sel = signal('dash');
  /** Ô tìm kiếm (thu icon lúc hẹp) đang mở lại để nhập. */
  protected readonly tnSearchOpen = signal(false);
  protected readonly selC = signal('dash');
  protected readonly selE = signal('dash');

  protected get items(): HrmNavItem[] {
    return [
      { key: 'dash', label: this.tr('navDashboard') },
      { key: 'hr', label: this.tr('navStaff') },
      { key: 'att', label: this.tr('navAttendance') },
      { key: 'pay', label: this.tr('navPayroll') },
      { key: 'rep', label: this.tr('navReport') },
    ];
  }
  protected get items2(): HrmNavItem[] {
    return [
      { key: 'dash', label: this.tr('navDashboard') },
      { key: 'price', label: this.tr('navPricing') },
    ];
  }
  protected get iconItems(): HrmNavItem[] {
    return [
      { key: 'dash', label: this.tr('navDashboard'), icon: IconLayoutDashboard },
      { key: 'hr', label: this.tr('navStaff'), icon: IconUsers },
      { key: 'att', label: this.tr('navAttendance'), icon: IconCalendarTime },
      { key: 'rep', label: this.tr('navReport'), icon: IconReportAnalytics },
    ];
  }
  protected get products() {
    return [
      { name: this.tr('prodAttendance'), desc: this.tr('prodAttendanceDesc'), icon: IconCalendarTime },
      { name: this.tr('prodStaff'), desc: this.tr('prodStaffDesc'), icon: IconUsers },
      { name: this.tr('prodReport'), desc: this.tr('prodReportDesc'), icon: IconReportAnalytics },
      { name: this.tr('prodDashboard'), desc: this.tr('prodDashboardDesc'), icon: IconLayoutDashboard },
    ];
  }

  protected readonly when = [
    'docs.topNav.when1',
    'docs.topNav.when2',
    'docs.topNav.when3',
  ];
}
